/* Phù Sa Ký – THƯ VIỆN, chuỗi khung điện ảnh (Cảnh 01–02, bản thiết kế §4).
   480x270, letterbox 2.39:1 (vùng vẽ 480x202, lệch y=34). Ánh nắng chiều xiên từ cửa sổ bên trái.
   Dựng: node <pxl>/bin/pxl.js build library_cinematic.px.js --out out */
pal({
  k:"#0b0604", q:"#150c06", d:"#24150b", D:"#3a2210", s:"#4a2c12", S:"#5e3a1a",
  b:"#7a4a24", B:"#8b5a2b", a:"#a0622d", c:"#c3a06a", e:"#e0b25a",
  y:"#ffd98c", Y:"#fff1c4", z:"#fffbe8", w:"#e8d6a6", W:"#f3e6bd", h:"#fff6dc",
  r:"#8b2a1c", R:"#c9605f", t:"#2f5a3a", m:"#8a4b66", n:"#3d4f7a", p:"#5a2a3a", l:"#b8863c",
  g:"#7f8f4a", G:"#566b34", f:"#9aa75e", v:"#3e5230", u:"#1d3558", U:"#3b5a8c",
  /* cuốn bìa xanh sẫm */
  "1":"#0e1e33", "2":"#17304f", "3":"#25507a", "4":"#4274a3", "5":"#6b9cc4",
  /* da An */
  "6":"#7a4a30", "7":"#b07a52", "8":"#d49a6a", "9":"#f0c090",
  /* tóc, áo, quần */
  o:"#120c0a", O:"#2a1c18", A:"#34505f", Z:"#5d8294", X:"#9cc0cc", T:"#262a3a", I:"#14161f",
  C:"#b98250", E:"#8a5a30", V:"#d9a46c",
  /* màn hình, nhựa */
  F:"#a8f0cc", H:"#52c99a", P:"#0f2a22", J:"#cfc3a8", j:"#9a8e74", K:"#6b624e",
  /* bụi */
  M:"#8f7f62", N:"#b3a380", Q:"#d6c9a4",
  /* kim loại, đồng */
  x:"#d4b25a"
})
ramps("kqdDsSbBaceyYz")

/* ---------- tiện ích ---------- */
const inPoly=(pts,x,y)=>{let ins=false;for(let i=0,j=pts.length-2;i<pts.length;j=i,i+=2){const xi=pts[i],yi=pts[i+1],xj=pts[j],yj=pts[j+1];if(((yi>y)!==(yj>y))&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)ins=!ins}return ins}
const BK=["r","u","a","w","t","m","s","l","n","p","c","B","U","C"]
const OY=34
const LY=(name,...items)=>layer(name,{y:OY},...items)
const BARS=()=>layer("bars",rect(0,0,480,OY,"k"),rect(0,OY+202,480,OY,"k"),hline(0,OY,480,"d"),hline(0,OY+201,480,"d"))
/* bụi lơ lửng trong vệt nắng */
const motes=(seed,polys,n,bright=true)=>(c)=>{const r=c.rng(seed);let k=0,t=0;while(k<n&&t<9000){t++;const x=r()*480|0,y=r()*202|0;if(polys.some(p=>inPoly(p,x,y))){c.px(x,y,r()<.35?"z":(bright?"Y":"y"));if(r()<.18)c.px(x+1,y,"y");k++}}}
/* quay một đa giác quanh (cx,cy) */
const rot=(pts,cx,cy,a)=>{const s=Math.sin(a),co=Math.cos(a),o=[];for(let i=0;i<pts.length;i+=2){const dx=pts[i]-cx,dy=pts[i+1]-cy;o.push(Math.round(cx+dx*co-dy*s),Math.round(cy+dx*s+dy*co))}return o}
const rq=(x,y,w,h)=>[x,y,x+w,y,x+w,y+h,x,y+h]

/* hàng sách xa (mờ, tối) làm hậu cảnh */
const bookRow=(c,x0,x1,y0,hh,seed,dim=0)=>{
  const r=c.rng(seed);c.rect(x0,y0,x1-x0,hh,"q");let x=x0+1;
  while(x<x1-2){const w=2+(r()*5|0),h=Math.round(hh*(.5+r()*.45)),col=BK[r()*BK.length|0],top=y0+hh-h;
    c.rect(x,top,w,h,col);c.vline(x+w-1,top,h,"d");if(w>2)c.vline(x,top+1,h-1,"Y");
    if(r()<.5)c.hline(x,top+2+(r()*5|0),w,"w");if(r()<.3)c.hline(x,top+h-6,w,"e");x+=w;if(r()<.08)x+=3+(r()*5|0)}
}
const plank=(c,x0,x1,y,col="B",hi="c")=>{c.rect(x0,y,x1-x0,4,col);c.hline(x0,y,x1-x0,hi);c.hline(x0,y+3,x1-x0,"k")}

/* ---------- chữ có dấu tiếng Việt (nhũ vàng trên bìa): phông 5x7 ---------- */
const G5={
 A:[".###.","#...#","#...#","#####","#...#","#...#","#...#"],
 B:["####.","#...#","#...#","####.","#...#","#...#","####."],
 C:[".####","#....","#....","#....","#....","#....",".####"],
 D:["####.","#...#","#...#","#...#","#...#","#...#","####."],
 G:[".####","#....","#....","#..##","#...#","#...#",".####"],
 H:["#...#","#...#","#...#","#####","#...#","#...#","#...#"],
 I:["#####","..#..","..#..","..#..","..#..","..#..","#####"],
 L:["#....","#....","#....","#....","#....","#....","#####"],
 N:["#...#","##..#","##..#","#.#.#","#..##","#..##","#...#"],
 O:[".###.","#...#","#...#","#...#","#...#","#...#",".###."],
 S:[".####","#....","#....",".###.","....#","....#","####."],
 U:["#...#","#...#","#...#","#...#","#...#","#...#",".###."],
}
const MARK={
 circ:[[1,-1],[2,-2],[3,-1]], breve:[[0,-2],[1,-1],[2,-1],[3,-1],[4,-2]],
 grave:[[0,-4],[1,-3]], hook:[[2,-3],[3,-3],[3,-2],[2,-1]], horn:[[5,0],[5,1]], dot:[[2,8]], bar:[[-1,3]]
}
/* mỗi ký tự: [chữ gốc, ...dấu] */
const VN={"Ị":["I","dot"],"Ử":["U","horn","hook"],"Đ":["D","bar"],"Ồ":["O","circ","grave"],"Ô":["O","circ"],"Ằ":["A","breve","grave"]}
/* vẽ chuỗi tại (x,y), scale s; flake(x,y)=>true thì bỏ điểm (nhũ bong); trả về độ rộng */
const vnText=(c,x,y,str,s,col,hi,sh,flake)=>{
  let cx=x;
  for(const ch of str){
    if(ch===" "){cx+=4*s;continue}
    const spec=VN[ch]||[ch],g=G5[spec[0]];if(!g){cx+=6*s;continue}
    const put=(gx,gy,cc)=>{const px=cx+gx*s,py=y+gy*s;if(flake&&flake(px,py))return;if(sh)c.rect(px+Math.max(1,s>>1),py+Math.max(1,s>>1),s,s,sh);c.rect(px,py,s,s,cc||col)}
    g.forEach((row,gy)=>{for(let gx=0;gx<5;gx++)if(row[gx]==="#")put(gx,gy)});
    spec.slice(1).forEach(m=>MARK[m].forEach(([gx,gy])=>put(gx,gy)));
    if(hi)g.forEach((row,gy)=>{for(let gx=0;gx<5;gx++)if(row[gx]==="#"&&(gy===0||g[gy-1][gx]!=="#")){const px=cx+gx*s,py=y+gy*s;if(!(flake&&flake(px,py)))c.hline(px,py,s,hi)}});
    cx+=6*s;
  }
  return cx-x
}
const vnWidth=(str,s)=>{let w=0;for(const ch of str)w+=ch===" "?4*s:6*s;return w-s}

