/* =====================================================================
   AN – nhìn nghiêng, hướng sang phải. Viền sáng ngược (nắng từ cửa sổ bên trái).
   ===================================================================== */
const rimLeft=(c)=>{const W=c.w,H=c.h,o=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(!c.is(x,y,"*"))continue;
  if(!c.is(x-1,y,"*"))o.push([x,y,"e"]);else if(!c.is(x-2,y,"*"))o.push([x,y,"a"]);
  else if(!c.is(x,y-1,"*"))o.push([x,y,"y"])}o.forEach(([x,y,k])=>c.px(x,y,k))}
/* đầu nhìn nghiêng; expr: "calm" | "frown" | "startle" | "down" */
const headSide=(c,hx,hy,expr="calm",tilt=0)=>{
  c.rect(hx-6,hy+10,12,14,"7");c.rect(hx-6,hy+10,5,14,"6");                    /* cổ */
  c.ellipse(hx,hy,13,15,"7");c.ellipse(hx-7,hy+2,6,12,"6");c.ellipse(hx+5,hy+3,4,5,"8");                    /* sọ: nửa sau tối hơn (ngược sáng) */
  c.poly([hx+6,hy-2,hx+13,hy+3,hx+8,hy+5],"7");                                /* mũi */
  c.px(hx+13,hy+3,"8");c.hline(hx+8,hy+10,5,"6");                              /* môi */
  c.poly([hx+3,hy+11,hx+12,hy+11,hx+8,hy+16,hx+2,hy+15],"7");                 /* cằm */
  /* tóc */
  c.poly([hx-14,hy+2,hx-13,hy-12,hx-4,hy-18,hx+8,hy-15,hx+13,hy-7,hx+8,hy-8,hx+4,hy-6,hx-2,hy-6,hx-5,hy+4,hx-8,hy+10,hx-13,hy+9],"o");
  c.ellipse(hx-2,hy-11,12,6,"O");
  c.poly([hx-13,hy+3,hx-8,hy+3,hx-9,hy+12,hx-13,hy+10],"o");
  /* tai */
  c.ellipse(hx-1,hy+3,3,5,"8");c.px(hx-2,hy+2,"6");
  /* mắt + mày */
  if(expr==="startle"){c.rect(hx+6,hy-2,4,4,"W");c.rect(hx+8,hy-1,2,3,"o");c.hline(hx+5,hy-6,6,"o");c.px(hx+11,hy-7,"o");c.rect(hx+9,hy+11,3,3,"k")}
  else if(expr==="frown"){c.hline(hx+6,hy-2,4,"W");c.px(hx+9,hy-2,"o");c.px(hx+8,hy-2,"o");c.line(hx+5,hy-5,hx+11,hy-3,"o")}
  else if(expr==="down"){c.hline(hx+6,hy,4,"o");c.line(hx+5,hy-3,hx+11,hy-3,"o")}
  else{c.hline(hx+6,hy-2,3,"W");c.px(hx+8,hy-2,"o");c.px(hx+9,hy-2,"o");c.hline(hx+5,hy-5,6,"o")}
}
