/* =====================================================================
   KHUNG 07 – CẬN CẢNH BÌA: nhũ vàng "Lịch sử Đồng bằng sông Cửu Long" hiện ra dưới tay An
   ba trạng thái: 0 phủ bụi (chỉ thấy bóng chữ) · 1 đang phủi giữa chừng · 2 lộ rõ
   ===================================================================== */
const CX=90,CY=4,CW=300,CH=196,SP=26                                           /* bìa + gáy */
const hsh=(x,y)=>((x*73856093^y*19349663)>>>0)%100
/* nhũ bong tróc: nhiều hơn ở mép dưới/phải, nơi tay người đọc chạm nhiều nhất */
const flakeAt=(x,y)=>hsh(x,y)<(2+Math.round(((x-CX)/CW)*6+((y-CY)/CH)*7))
const coverBody=(c)=>{
  c.rect(CX,CY,CW,CH,"2");
  /* vải bìa: dệt chéo rất nhẹ, hai sắc */
  for(let y=CY;y<CY+CH;y++)for(let x=CX+SP;x<CX+CW;x++){const k=(x+y*2)%6;if(k===0)c.px(x,y,"3");else if(k===3&&y%2)c.px(x,y,"1")}
  /* cạnh vát: sáng trên/trái, tối dưới/phải */
  c.rect(CX+SP,CY,CW-SP,2,"4");c.rect(CX+SP,CY+2,CW-SP,1,"3");c.rect(CX+CW-3,CY,3,CH,"1");c.rect(CX+SP,CY+CH-3,CW-SP,3,"1");
  /* gáy sách: tối hơn, có gờ nổi nhũ vàng */
  c.rect(CX,CY,SP,CH,"1");c.rect(CX,CY,3,CH,"2");c.vline(CX+SP-1,CY,CH,"d");c.vline(CX+SP,CY,CH,"3");c.vline(CX+SP+1,CY,CH,"4");
  [26,62,98,134,170].forEach(y=>{c.rect(CX+2,CY+y,SP-4,4,"2");c.hline(CX+2,CY+y,SP-4,"3");c.hline(CX+3,CY+y+1,SP-6,"l");c.hline(CX+2,CY+y+3,SP-4,"1")});
  /* sờn mép: lộ lớp giấy bồi be ở góc và dọc các cạnh */
  const r=c.rng(17);
  c.poly([CX+CW-22,CY,CX+CW,CY,CX+CW,CY+18],"c");c.poly([CX+CW-16,CY,CX+CW,CY,CX+CW,CY+12],"w");
  c.poly([CX+CW-26,CY+CH,CX+CW,CY+CH,CX+CW,CY+CH-20],"c");c.poly([CX+CW-18,CY+CH,CX+CW,CY+CH,CX+CW,CY+CH-12],"w");
  c.poly([CX+SP,CY+CH,CX+SP+16,CY+CH,CX+SP,CY+CH-14],"c");
  for(let i=0;i<34;i++){const x=CX+SP+8+(r()*(CW-SP-16)|0);c.hline(x,CY,2+(r()*5|0),"c");if(r()<.7)c.hline(x,CY+CH-1,2+(r()*7|0),"c")}
  for(let i=0;i<26;i++){const y=CY+8+(r()*(CH-16)|0);c.vline(CX+CW-1,y,2+(r()*6|0),"c");}
  /* vài vết xước chéo do ma sát với ngăn tủ lâu năm */
  [[CX+CW-120,CY+CH-70,CX+CW-70,CY+CH-44],[CX+CW-100,CY+CH-76,CX+CW-64,CY+CH-60],[CX+CW-60,CY+CH-92,CX+CW-34,CY+CH-80]].forEach(([x0,y0,x1,y1])=>{c.line(x0,y0,x1,y1,"1");c.line(x0,y0-1,x1,y1-1,"3")})
}
/* ô trang trí dập nhũ: khung kép + bông sen (cánh sen ép khô rơi ra sau này) */
const coverGold=(c)=>{
  const x0=CX+SP+10,y0=CY+10,w=CW-SP-20,h=CH-20,F=flakeAt;
  const seg=(x,y,len,vert)=>{for(let i=0;i<len;i++){const px=vert?x:x+i,py=vert?y+i:y;if(!F(px,py))c.px(px,py,"e");if(!F(px,py+1)&&!vert)c.px(px,py+1,"l")}}
  seg(x0,y0,w,false);seg(x0,y0+h,w,false);seg(x0,y0,h,true);seg(x0+w,y0,h,true);
  seg(x0+5,y0+5,w-10,false);seg(x0+5,y0+h-5,w-10,false);seg(x0+5,y0+5,h-10,true);seg(x0+w-5,y0+5,h-10,true);
  /* hoa văn góc */
  [[x0+9,y0+9],[x0+w-9,y0+9],[x0+9,y0+h-9],[x0+w-9,y0+h-9]].forEach(([x,y])=>{for(let d=-3;d<=3;d++){if(!F(x+d,y))c.px(x+d,y,"l");if(!F(x,y+d))c.px(x,y+d,"l")}});
  const mx=CX+SP+Math.round((CW-SP)/2);
  /* bông sen ở dưới nhan đề */
  const lot=(ox,oy)=>{
    const P=(pts,col)=>c.poly(pts.map((v,i)=>i%2?oy+v:ox+v),col);
    P([0,-18,6,-8,0,2,-6,-8],"l");P([-8,-8,-16,-16,-10,-2,-2,2],"l");P([8,-8,16,-16,10,-2,2,2],"l");
    P([-14,-2,-26,-8,-18,4,-4,4],"l");P([14,-2,26,-8,18,4,4,4],"l");
    c.line(ox-30,oy+8,ox+30,oy+8,"l");c.line(ox-22,oy+11,ox+22,oy+11,"l");
    c.px(ox,oy-14,"y");c.px(ox-12,oy-10,"y");c.px(ox+12,oy-10,"y")
  }
  lot(mx,CY+CH-38);
  /* nhan đề */
  const put=(str,y,s)=>{const w=vnWidth(str,s);vnText(c,mx-Math.round(w/2),y,str,s,"e","y","1",F)};
  put("LỊCH SỬ",CY+38,4);
  c.hline(mx-60,CY+74,120,"e");c.hline(mx-60,CY+76,120,"l");
  put("ĐỒNG BẰNG",CY+88,3);
  put("SÔNG CỬU LONG",CY+118,3);
  /* ô nhỏ tác giả ở dưới: bị mờ gần hết, không đọc được tên ("không thấy tên người ghi") */
  c.hline(mx-30,CY+CH-20,60,"l");
}
/* lớp bụi: ngoài vệt phủi thì phủ dày theo dither; hàm wipe(x,y)=>true nếu đã sạch */
const B4=[[0,8,2,10],[12,4,14,6],[3,11,1,9],[15,7,13,5]]
const coverDust=(wipe,dens,ridge)=>(c)=>{
  for(let y=CY;y<CY+CH;y++)for(let x=CX;x<CX+CW;x++){
    if(wipe(x,y)){ /* đã sạch: còn vài hạt ở góc */
      const e=Math.min(Math.abs(x-CX-CW),Math.abs(y-CY-CH),Math.abs(x-CX),Math.abs(y-CY));
      if(e<9&&B4[y&3][x&3]<(9-e)*.45)c.px(x,y,"M");continue}
    const g=c.is(x,y,"ely1")&&!c.is(x,y,"1"),d=dens-.1*Math.sin(x*.17+y*.09)+.05*Math.cos(y*.23)-(g?.42:0);
    if(d*16>B4[y&3][x&3])c.px(x,y,d>.74?"N":(d>.52?"M":"Q"));else if(((x*5+y*3)%11)===0)c.px(x,y,"Q")}
  if(ridge)ridge(c)
}
/* nắng xiên từ trên trái: vệt sáng quét ngang bìa */
const coverLight=[poly([CX-40,CY-10,CX+90,CY-10,CX+CW+40,CY+CH+10,CX+CW-90,CY+CH+10],"y")]
const thumb=(c,x,y,flip=1)=>{c.ellipse(x,y,22,14,"8");c.ellipse(x,y-4,20,8,"9");c.ellipse(x+flip*8,y+6,14,6,"7");c.line(x-8*flip,y-2,x+10*flip,y-2,"7")}
/* ngón cái giữ mép dưới bìa (cả hai tay) */
const holdThumbs=(c)=>{thumb(c,CX+60,CY+CH-2,1);thumb(c,CX+CW-50,CY+CH-2,-1);
  poly([CX+34,CY+CH+6,CX+86,CY+CH+6,CX+80,CY+CH-6,CX+40,CY+CH-6],"A")}

const reveal=(name,opts)=>scene(name,{w:480,h:270,layers:true},
  LY("bg",rect(0,0,480,202,"q"),
    (c)=>{const r=c.rng(8);for(let i=0;i<22;i++){const x=r()*480|0,y=r()*202|0,rr=4+(r()*9|0);if(x>CX-8&&x<CX+CW+8)continue;c.circ(x,y,rr,"d");c.ring(x,y,rr,"s")}},
    ellipse(CX+CW/2,CY+CH+4,CW/2+30,10,"k",true)),
  LY("cover",coverBody,coverGold,
    /* bóng đổ cạnh dưới do bìa sách cũ hơi cong */
    shade([CX+SP,CY+CH-20,CW-SP,20],1,.5),
    coverDust(opts.wipe,opts.dens,opts.ridge)),
  LY("hand",...(opts.hand||[holdThumbs])),
  glow("ly",{r:6,strength:opts.glow||0}),
  layer("sun",{light:true,y:OY},...coverLight),
  LY("fx",motes(opts.seed,[[CX-40,CY-10,CX+90,CY-10,CX+CW+40,CY+CH+10,CX+CW-90,CY+CH+10]],opts.motes||26)),
  layer("vig",{shade:true,y:OY},poly([0,0,60,0,0,202],"k"),poly([420,202,480,150,480,202],"k"),poly([0,202,40,202,0,160],"k")),
  BARS())

/* 0: chưa phủi – chỉ thấy bóng mờ của những nét nhũ dưới lớp bụi */
