/* 1: lòng bàn tay lướt từ trái sang, chữ "LỊCH SỬ" bắt đầu hiện */
const wipeX1=(y)=>CX+SP+118+Math.round(16*Math.sin(y*.045))+Math.round((y-100)*.18)
